namespace ghidra.app.plugin.core.symboltree.actions;

using docking.action;
using ghidra.app.events;
using ghidra.app.plugin.core.symboltree;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.program.util;

public class SelectionAction : SymbolTreeContextAction {

	private Plugin plugin;

	public SelectionAction(Plugin plugin) : base("Make Selection", plugin.getName())
    {
		this.plugin = plugin;
		setPopupMenuData(new MenuData(new string[] { "Make Selection" }, MIDDLE_MENU_GROUP));
	}

	/* @Override */
	protected bool isEnabledForContext(SymbolTreeActionContext context) {
		foreach (Symbol s in context.getSymbols()) {
			if (!s.isExternal()) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	public void actionPerformed(SymbolTreeActionContext context) {
		AddressSet set = new AddressSet();
		foreach (Symbol symbol in context.getSymbols()) {
			if (symbol.isExternal()) {
				continue;
			}
			object symbolObject = symbol.getObject();
			if (symbolObject is Namespace) {
				Namespace @namespace = (Namespace) symbolObject;
				set.add(@namespace.getBody());
			}
			else if (symbolObject is Variable) {
				ProgramLocation loc = symbol.getProgramLocation();
				set.addRange(loc.getAddress(), loc.getAddress());
			}
			else if (symbolObject is CodeUnit) {
				CodeUnit cu = (CodeUnit) symbolObject;
				set.addRange(cu.getMinAddress(), cu.getMaxAddress());
			}
		}

		if (!set.isEmpty()) {
			plugin.firePluginEvent(new ProgramSelectionPluginEvent(plugin.getName(),
				new ProgramSelection(set), context.getProgram()));
		}
	}
}
